/**
 * Colour math shared by the genome's MIN_CONTRAST constraint and the immune
 * scan: WCAG 2.2 contrast (`ui_ux/tokens.py`), CIE76 delta E and literal colour
 * extraction (`execution_fabric/verifiers.py`).
 *
 * Python evaluates `x ** 2.4` and `t ** (1/3)` with the C library's `pow`,
 * which V8's `Math.pow` does not reproduce bit for bit (32 of the 256 sRGB
 * channel values and ~9% of cube roots differ by one ulp). So:
 * - the 256 linearised channel values are a table generated by Python
 *   (`SRGB_LINEAR`, checked against the fixture, and equal to the correctly
 *   rounded values);
 * - the cube root is computed correctly rounded (double-double refinement).
 *   glibc's `pow` is itself not always correctly rounded, so a one-ulp
 *   difference in a Lab coordinate remains possible; every delta E is rounded
 *   to 3 places and the fixture's sampled pairs all agree.
 */
import { PY_WORD_CLASS, SRGB_LINEAR } from './python-tables';
import { roundTo, sortedUnique } from './python';

function channel(hex: string, at: number): number {
  const value = Number.parseInt(hex.slice(at, at + 2), 16);
  if (Number.isNaN(value)) throw new RangeError(`not a hex colour: ${hex}`);
  return value;
}

/** `int(h[i:i+2], 16)` for each channel, after `lstrip("#")`. */
function channels(hexValue: string): [number, number, number] {
  const h = hexValue.replace(/^#+/, '');
  return [channel(h, 0), channel(h, 2), channel(h, 4)];
}

function linear(value: number): number {
  const out = SRGB_LINEAR[value];
  if (out === undefined) throw new RangeError(`channel out of range: ${value}`);
  return out;
}

/** WCAG 2.2 relative luminance (sRGB). */
export function relativeLuminance(hexValue: string): number {
  const [r, g, b] = channels(hexValue).map(linear) as [number, number, number];
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/** `wcag_contrast_ratio`: rounded to 2 places like Python's `round(x, 2)`. */
export function wcagContrastRatio(foreground: string, background: string): number {
  const a = relativeLuminance(foreground);
  const b = relativeLuminance(background);
  return roundTo((Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05), 2);
}

const SPLIT = 134217729; // 2^27 + 1, Dekker's splitter

function twoProduct(a: number, b: number): [number, number] {
  const p = a * b;
  let t = SPLIT * a;
  const ah = t - (t - a);
  const al = a - ah;
  t = SPLIT * b;
  const bh = t - (t - b);
  const bl = b - bh;
  return [p, ah * bh - p + ah * bl + al * bh + al * bl];
}

function twoSum(a: number, b: number): [number, number] {
  const s = a + b;
  const bb = s - a;
  return [s, a - (s - bb) + (b - bb)];
}

// The double nearest 1/3 is 1/3 - 1/(3 * 2^54); x ** that = cbrt(x) * (1 - D ln x) to well past double precision.
const THIRD_DEFICIT = 1 / (3 * 2 ** 54);

/** `x ** (1 / 3)` for x > 0, correctly rounded. */
export function powThird(x: number): number {
  const c = Math.cbrt(x);
  const [c2, c2Low] = twoProduct(c, c);
  const [c3, c3Low] = twoProduct(c2, c);
  const residual = x - c3 - (c3Low + c2Low * c);
  const low = residual / (3 * c * c) - c * THIRD_DEFICIT * Math.log(x);
  const [s, e] = twoSum(c, low);
  return s + e;
}

function labF(t: number): number {
  return t > 216 / 24389 ? powThird(t) : ((24389 / 27) * t + 16) / 116;
}

function srgbToLab(hexValue: string): [number, number, number] {
  const [r, g, b] = channels(hexValue).map(linear) as [number, number, number];
  const x = (r * 0.4124 + g * 0.3576 + b * 0.1805) / 0.95047;
  const y = (r * 0.2126 + g * 0.7152 + b * 0.0722) / 1.0;
  const z = (r * 0.0193 + g * 0.1192 + b * 0.9505) / 1.08883;
  const [fx, fy, fz] = [labF(x), labF(y), labF(z)];
  return [116 * fy - 16, 500 * (fx - fy), 200 * (fy - fz)];
}

/** `delta_e76`: CIE76 distance, rounded to 3 places. */
export function deltaE76(a: string, b: string): number {
  const la = srgbToLab(a);
  const lb = srgbToLab(b);
  let total = 0;
  for (let i = 0; i < 3; i += 1) {
    const d = (la[i] ?? 0) - (lb[i] ?? 0);
    total += d * d;
  }
  return roundTo(Math.sqrt(total), 3);
}

// `#[0-9a-fA-F]{6}\b`: after six hex digits (word characters), `\b` means "not followed by a Python word character".
const HEX_COLOR = new RegExp(`#[0-9a-fA-F]{6}(?!${PY_WORD_CLASS})`, 'gu');

/** `colors_in`: every literal `#rrggbb`, lower-cased, sorted and de-duplicated. */
export function colorsIn(text: string): string[] {
  return sortedUnique(Array.from(text.matchAll(HEX_COLOR), (m) => m[0].toLowerCase()));
}
